head.script:
// https://inswave01.atlassian.net/browse/WAEA-1516
// https://inswave01.atlassian.net/browse/WAEA-1517



// 담당 범위 : useMonthYearFormat 가이드 전 항목 (con_useMonthYearFormat / con_pickerType / con_ioFormat 3개, Body Column 1개)
//  - "Body Column 에서만 동작하며 다른 영역의 Column 에 설정 시 무시됩니다." 는 validation 에서 제외 (column 샘플 관례, 설정 영역 con 옵션 미생성, Body Column 에만 설정)
//  - "Column 의 ioFormat, displayFormat 속성에 날짜 관련 마스크 문자를 설정하려면 dataType='date' 여야 합니다." 는 ioFormat / displayFormat 자체의 전제라 validation 에서 제외 (대상 Column 은 dataType='date' 고정, 라벨 [전제] 로 안내)
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[column > P > useMonthYearFormat]<br/>inputType='calendar' 인 Column 에서 팝업 달력의 상단 연도/월 SelectBox 가 표시되는 순서를 설정합니다.",
    "validation" : [
        "true 설정 시, Column 의 pickerType='selectbox' 일때 팝업 달력의 월 SelectBox 가 연도 SelectBox 앞에 표시됩니다.",
        "Column 의 pickerType='dynamic' 이면 팝업 달력의 연도/월 SelectBox 의 순서가 변경되지 않습니다.",
        "true 설정 시, DataList 값은 ioFormat 속성에 관계없이 연도/월/일 순서('yyyyMMdd', 'yyyyMM' 등)로 저장됩니다.",
        "false 설정 시, 팝업 달력의 연도/월 SelectBox 의 순서가 변경되지 않습니다.",
        "미설정 시, 팝업 달력의 연도/월 SelectBox 의 순서가 변경되지 않습니다.",
        "false 설정 시, DataList 의 Cell 값은 ioFormat 속성의 포맷으로 저장됩니다.",
        "useMonthYearFormat='true' 일때 ioFormat 속성은 Cell 이 편집 상태일때만 적용되며 DataList 에 저장되는 값은 ioFormat 속성에 관계없이 연/월/일 순서로 저장됩니다."
    ]
}



scwin.onpageload = async function () {
    // Global DataList(gdl_boolean 등) 생성 호출
    $c.gcm.createCommonDatalist();

    // 정적 select1 은 초기 selectedIndex 가 적용되지 않으므로 기본값 명시 설정 (gdl_boolean 코드 "2" = true)
    con_useMonthYearFormat.setValue("2");
    con_pickerType.setValue("selectbox");
    con_ioFormat.setValue("ddMMyyyy");

    // 달력 아이콘 / 팝업 달력 안을 클릭하면 결과 출력 (페이지 로딩 시 1회만 등록)
    document.addEventListener("click", scwin.onDocumentClick, true);

    // comp 초기 생성
    await scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// ioFormat 별 calendarValueType / displayFormat / 초기값 (2026-10-15)
//  - ymd : DataList 에 연/월/일 순서로 저장된 값 (useMonthYearFormat='true' 일때 넣는 값)
//  - io  : ioFormat 포맷으로 저장된 값 (미설정 / false 일때 넣는 값)
scwin.formatInfo = {
    "ddMMyyyy" : { "calendarValueType" : "yearMonthDate", "displayFormat" : "yyyy-MM-dd", "ymd" : "20261015", "io" : "15102026" },
    "MMddyyyy" : { "calendarValueType" : "yearMonthDate", "displayFormat" : "yyyy-MM-dd", "ymd" : "20261015", "io" : "10152026" },
    "MMyyyy" : { "calendarValueType" : "yearMonth", "displayFormat" : "yyyy-MM", "ymd" : "202610", "io" : "102026" }
};



// comp 생성
//  - useMonthYearFormat / pickerType / ioFormat 은 Body Column(cdate) 에만 설정 (useMonthYearFormat 미설정은 속성 자체를 넣지 않는다)
//  - Body Column 은 inputType="calendar" + dataType="date" + viewType="icon" (팝업 달력은 달력 아이콘으로 연다)
scwin.comp_init = async function () {
    // 기존 target / dataList / label 삭제
    if (typeof target1 !== 'undefined' && target1) {
        target1.remove();
    }
    if (typeof dlt_bind !== 'undefined' && dlt_bind) {
        $p.data.remove("dlt_bind");
    }
    if (typeof label1 !== 'undefined' && label1) {
        label1.remove();
    }

    // 테스트 정보 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] date Column 은 dataType=date, displayFormat 은 yyyy-MM-dd (ioFormat=MMyyyy 이면 calendarValueType=yearMonth, displayFormat=yyyy-MM)\n초기 Cell 값은 2026-10-15 (useMonthYearFormat=true 이면 연/월/일 순서 값, 그 외는 ioFormat 포맷 값으로 넣음)\n[절차] date 셀 클릭 -> 입력창 오른쪽 달력 아이콘 클릭 -> 팝업 달력에서 다른 날짜 클릭 (yearMonth 는 월 SelectBox 에서 다른 월 선택 후 확인 버튼 클릭) -> 결과창 클릭으로 편집 종료\n[확인] 셀 클릭 시 편집 창 값, 팝업이 열리면 위쪽 SelectBox 순서(왼쪽부터), 편집 종료 시 DataList 저장값과 화면 표시가 출력됩니다."', '', 'label1');

    // 조건 설정 (gdl_boolean 은 getText(), 자체 값 select 는 getValue())
    let cUseMonthYearFormat = con_useMonthYearFormat.getText();
    let cPickerType = con_pickerType.getValue();
    let cIoFormat = con_ioFormat.getValue();
    let fmt = scwin.formatInfo[cIoFormat];

    // dataList 생성 (calendar Column 바인딩 컬럼은 dataType="date")
    let strNameSpace = $c.gcm.getNameSpace();
    let strDlt = '';
    strDlt += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="cdate" name="cdate" dataType="date"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);
    dlt_bind.setJSON([{ "cdate" : (cUseMonthYearFormat === 'true') ? fmt.ymd : fmt.io }], false);

    // cdate Column 속성
    let attrCol = ' calendarValueType="' + fmt.calendarValueType + '" ioFormat="' + cIoFormat + '" displayFormat="' + fmt.displayFormat + '" pickerType="' + cPickerType + '"';
    attrCol += (cUseMonthYearFormat === '') ? '' : ' useMonthYearFormat="' + cUseMonthYearFormat + '"';

    // 이벤트 바인딩 (편집 종료 시 저장값 출력)
    let eList = $c.gcm.createEList(["onviewchange"]);

    // target 생성
    let grp_comp = $c.gcm.getTestGroup();
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' ' + eList + ' dataList="data:dlt_bind" checkAllType="false" id="" style="width:300px;height:150px;">';
    strTarget += '<w2:caption style="" id="caption1" value="this is a grid caption."></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="200" style="" inputType="text" id="column1" value="date"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="200" style="" id="cdate" inputType="calendar" dataType="date" viewType="icon"' + attrCol + '></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin["target1"] = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );

    // validation 3, 6, 7 : 생성 시 DataList 저장값과 화면 표시
    scwin.printCellData("생성");
}



// DataList 저장값과 화면 표시(Cell 텍스트) 출력
scwin.printCellData = function (title) {
    let td = document.querySelector("td[id*='" + target1.id + "_cell_0_0']");
    wf_body_bottom.getObj("scwin").setReturnValue(title + " -> DataList 저장값 '" + dlt_bind.getCellData(0, "cdate") + "' / 화면 표시 '" + (td ? td.textContent : "") + "'");
}



// validation 3, 6, 7 판정 출력 : 편집 종료 시 DataList 저장값과 화면 표시
scwin.target1_onviewchange = function (info) {
    scwin.printCellData("편집 종료");
}



// 화면에 보이는 요소인지 확인
scwin.isVisible = function (elem) {
    return !!elem && elem.offsetWidth > 0 && elem.offsetHeight > 0 && getComputedStyle(elem).visibility !== "hidden";
}



// 화면에 열려 있는 target1 의 팝업 달력 render 반환 (없으면 null)
scwin.getOpenedCalendar = function () {
    if (typeof target1 === 'undefined' || !target1) {
        return null;
    }
    let cals = document.querySelectorAll("div.w2calendar[id*='G_" + target1.id + "__']");
    for (let i = 0; i < cals.length; i++) {
        if (scwin.isVisible(cals[i])) {
            return cals[i];
        }
    }
    return null;
}



// date 셀 / 달력 아이콘 / 팝업 달력 안 클릭 시 결과 출력
scwin.onDocumentClick = function (e) {
    let elem = e.target;
    if (!elem || !elem.closest || typeof target1 === 'undefined' || !target1) {
        return;
    }
    let btn = elem.closest("button.w2inputCalendar_button");
    let cal = elem.closest("div.w2calendar");
    let td = elem.closest("td[id*='" + target1.id + "_cell_']");
    if ((btn && btn.id.indexOf("G_" + target1.id + "__") >= 0) || (cal && cal.id.indexOf("G_" + target1.id + "__") >= 0)) {
        setTimeout(scwin.printCalendarHeader, 200);
    } else if (td) {
        setTimeout(scwin.printEditValue, 200);
    }
}



// validation 7 판정 출력 : 편집 상태(입력창 포커스)일때 편집 창 값 (ioFormat 포맷 적용 여부)
scwin.printEditValue = function () {
    let input = document.activeElement;
    if (!input || input.tagName !== "INPUT" || input.id.indexOf("G_" + target1.id + "__") < 0) {
        return;
    }
    wf_body_bottom.getObj("scwin").setReturnValue("편집 상태 -> 편집 창 값 '" + input.value + "'");
}



// validation 1, 2, 4, 5 판정 출력 : 팝업 달력 위쪽 연도/월 구성(왼쪽부터)
//  - selectbox : 화면에 보이는 연도/월 SelectBox 를 왼쪽 위치 순으로 나열
//  - dynamic : 연도/월 SelectBox 대신 표시되는 연도/월 영역 텍스트
scwin.printCalendarHeader = function () {
    let cal = scwin.getOpenedCalendar();
    if (!cal) {
        return;
    }
    let header = "";
    let entity = cal.querySelector(".w2calendar_picker_header_dynamic_entity");
    if (scwin.isVisible(entity)) {
        let spans = entity.querySelectorAll("span");
        let text = spans.length ? Array.prototype.map.call(spans, function (sp) { return sp.textContent; }).join(" ") : entity.textContent;
        header = "연도/월 SelectBox 없음, 연도/월 영역 '" + text + "'";
    } else {
        let items = [];
        [["year", "연도"], ["month", "월"]].forEach(function (info) {
            let sel = cal.querySelector("[class*='w2calendar_selectbox_" + info[0] + "']");
            if (scwin.isVisible(sel)) {
                let lbl = sel.querySelector(".w2selectbox_label");
                items.push({ "left" : sel.getBoundingClientRect().left, "text" : info[1] + " SelectBox(" + (lbl ? lbl.textContent : "") + ")" });
            }
        });
        items.sort(function (a, b) { return a.left - b.left; });
        header = items.map(function (item) { return item.text; }).join(" -> ");
    }
    wf_body_bottom.getObj("scwin").setReturnValue("팝업 위쪽 : " + header);
}
